    static void GeometryAndDrag(PetWindow pet){using(PetDpi.Enter())GeometryAndDragPhysical(pet);}
    static void HudPlacement(PetWindow pet){using(PetDpi.Enter()){
        var atlas=Field<PetAtlas>(pet,"atlas");var hud=Field<PetOverlay>(pet,"hud");var popup=Field<PetOverlay>(pet,"popup");var area=pet.AllowedBounds;var allowed=(Rectangle)typeof(PetWindow).GetMethod("MotionBounds",Hidden).Invoke(pet,new object[]{area});pet.Motion.Position=new PointF(pet.Motion.Position.X,allowed.Top);pet.AdvanceOnce();var body=(RectangleF)typeof(PetWindow).GetMethod("BodyRectangle",Hidden).Invoke(pet,new object[]{atlas.IdleContentBounds,true});float scale=pet.RenderScale*pet.CapsuleFactor;Need(Field<bool>(pet,"hudBelow")&&hud.Top+7*scale>=body.Bottom+8*pet.RenderScale,"Top-edge capsule did not move below pet");Need(hud.Bottom<=area.Bottom+1,"Bottom capsule is off-screen");pet.Motion.Position=new PointF(pet.Motion.Position.X,pet.Motion.Position.Y+340*pet.RenderScale);pet.AdvanceOnce();Need(!Field<bool>(pet,"hudBelow"),"Capsule did not return above after leaving top edge");var before=pet.Bounds;pet.OpenPanel(true);Pump(370);Need(pet.Expanded&&!pet.DismissOnOutsideClick&&!hud.Visible,"Expanded card is not pinned until manual close");if(!Field<bool>(pet,"panelBelow"))Need(popup.Bottom<=pet.VisibleBodyScreenBounds.Top+5*scale,"Pinned card is not above the head");Pump(80);Need(pet.Bounds==before,"Pinned card shifted pet body");Invoke(pet,"PanelClick",new Point((int)(250*scale),(int)(22*scale)));Pump(370);Need(!pet.Expanded&&!popup.Visible&&hud.Visible,"Manual close did not restore capsule");var menu=Field<ContextMenuStrip>(pet,"menu");Need(!menu.Items.OfType<ToolStripMenuItem>().Any(item=>item.Checked),"Pet menu still shows checkmarks");
