    static void GeometryAndDragPhysical(PetWindow pet){
        var atlas=Field<PetAtlas>(pet,"atlas");var director=Field<PetAnimationDirector>(pet,"director");var area=pet.AllowedBounds;
        var allowed=(Rectangle)typeof(PetWindow).GetMethod("MotionBounds",Hidden).Invoke(pet,new object[]{area});pet.Location=new Point(allowed.Left,allowed.Top);
        var body=(RectangleF)typeof(PetWindow).GetMethod("BodyRectangle",Hidden).Invoke(pet,new object[]{atlas.IdleContentBounds,true});Need(body.Left>=area.Left+7*pet.RenderScale&&body.Top>=area.Top+7*pet.RenderScale,"Collision padding: "+pet.Text);
        pet.Motion.Position=new PointF(area.Left+area.Width/2-pet.Width/2,area.Top+area.Height/2-pet.Height/2);pet.Location=Point.Round(pet.Motion.Position);
        Point cursor=new Point(area.Left+area.Width/2,area.Top+area.Height/2);var origin=pet.Motion.Position;int generation=director.Generation;
        Invoke(pet,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,pet.Width/2,pet.Height/2,0));typeof(PetWindow).GetField("cursorStart",Hidden).SetValue(pet,cursor);
        Need(director.Generation==generation&&!atlas.DragHeld,"A simple press started a flying prefix: "+pet.Text);
        pet.DragTo(new Point(cursor.X+1,cursor.Y+1));Need(director.Generation==generation&&!pet.Motion.Dragging,"Pointer jitter entered drag mode: "+pet.Text);
        double maximum=0;for(int i=0;i<20;i++){var point=new Point(cursor.X+5+i*2,cursor.Y+8+i);var clock=Stopwatch.StartNew();pet.DragTo(point);maximum=Math.Max(maximum,clock.Elapsed.TotalMilliseconds);allowed=(Rectangle)typeof(PetWindow).GetMethod("MotionBounds",Hidden).Invoke(pet,new object[]{pet.AllowedBounds});var expected=PetMotion.Clamp(new PointF(origin.X+point.X-cursor.X,origin.Y+point.Y-cursor.Y),pet.Size,allowed);Need(pet.Motion.Position==expected&&pet.Location==Point.Round(expected),"Drag handler did not immediately move its native window: "+pet.Text);Need(director.Row==director.DragRow&&atlas.DragHeld,"Actual dragging has no held pose: "+pet.Text);}
        Need(maximum<150,"Drag handler blocks input: "+maximum);generation=director.Generation;
        Invoke(pet,"OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,pet.Width/2,pet.Height/2,0));
        Need(!pet.Motion.Dragging&&!atlas.DragHeld&&director.Generation>generation&&Field<string>(director,"kind")=="idle","Mouse release did not immediately stop the flight: "+pet.Text);
        if(atlas.IsVideo)Need(Field<Bitmap>(atlas,"previousVideo")==null,"Release blends the flight into a second character pose");
        pet.Motion.Sliding=false;pet.Motion.Velocity=PointF.Empty;
    }
    static void PanelFollow(PetWindow pet){using(PetDpi.Enter()){
        var director=Field<PetAnimationDirector>(pet,"director");var popup=Field<PetOverlay>(pet,"popup");var area=pet.AllowedBounds;
        foreach(bool tasks in new[]{true,false}){
            pet.Motion.Position=new PointF(area.Left+area.Width/2-pet.Width/2,area.Top+area.Height/2-pet.Height/2);pet.Motion.ResumeAutonomy();director.Restore(Field<Stopwatch>(pet,"watch").Elapsed.TotalSeconds);pet.AdvanceOnce();
            pet.OpenPanel(tasks);Pump(360);Need(pet.Expanded&&pet.PanelReveal==1&&popup.Visible,"Card failed to open: "+pet.Text);
            var position=pet.Location;var card=popup.Location;var size=pet.Size;pet.Motion.Drop(new PointF(160,30));Pump(180);
            Need(pet.Left-position.X>8&&director.Time>.08,"Expanded card paused pet motion or its animation director: "+pet.Text);
            Need(Math.Abs((popup.Left-card.X)-(pet.Left-position.X))<=2&&Math.Abs((popup.Top-card.Y)-(pet.Top-position.Y))<=2,"Open card did not follow the pet at its fixed offset: "+pet.Text);
            Need(pet.Expanded&&popup.Visible&&pet.Size==size&&pet.Motion.PressScale==1,"Following card closed, resized or pressed the pet: "+pet.Text);
            pet.Motion.Sliding=false;pet.Motion.Velocity=PointF.Empty;pet.OpenPanel(tasks);Pump(350);
        }
    }}
    static object VideoInput(string root,PetPack pack){if(!File.Exists(Path.Combine(root,@"engine\runtime\ffmpeg\ffmpeg.exe")))return new{skipped="Assets-only fixture"};var spec=new PetAnimationDirector(pack,new PetBehaviorProfile(),1);using(var atlas=new PetAtlas(pack))using(var image=new Bitmap(640,360))using(var g=Graphics.FromImage(image)){
