    }
    static object NativeWalk(string root,PetPack pack){if(!File.Exists(Path.Combine(root,@"engine\runtime\ffmpeg\ffmpeg.exe")))return new{skipped="Assets-only fixture"};return pack.Behavior.move.Select(i=>NativeWalkClip(root,pack,i)).ToArray();}
    sealed class SurfaceHost:Form {protected override bool ShowWithoutActivation{get{return true;}}public SurfaceHost(){ShowInTaskbar=false;FormBorderStyle=FormBorderStyle.FixedToolWindow;StartPosition=FormStartPosition.Manual;Bounds=new Rectangle(PetDisplays.All[0].WorkingArea.Left+100,100,1000,800);}}
    static object Visibility(string root,PetPack pack){using(var host=new SurfaceHost()){host.Show();Pump(30);PetSurface cached=CodexPetSurface.RefreshKnown(host.Handle,(uint)Process.GetCurrentProcess().Id);Need(cached!=null,"Visibility fixture is not available");using(var pet=PetWindow.Create(pack,new PetPreferences{CodexOnly=true,Roaming=false,Sound=false,PositionVersion=1},root)){pet.TrackLiveSurface=true;pet.SurfaceProvider=()=>cached;pet.AdvanceOnce();Need(pet.Visible,"Verified fixture pet did not appear");pet.OpenPanel(true);Pump(350);var samples=new List<object>();for(int i=0;i<3;i++){var clock=Stopwatch.StartNew();host.WindowState=FormWindowState.Minimized;cached=null;while(pet.Visible&&clock.ElapsedMilliseconds<500)Pump(5);long hidden=clock.ElapsedMilliseconds;Need(!pet.Visible&&hidden<150,"Pet waited for slow discovery after minimize: "+hidden);clock.Restart();host.WindowState=FormWindowState.Normal;while(!pet.Visible&&clock.ElapsedMilliseconds<500)Pump(5);long shown=clock.ElapsedMilliseconds;Need(pet.Visible&&shown<150&&pet.Expanded,"Pet did not immediately restore with its pinned panel: "+shown);samples.Add(new{hiddenMs=hidden,shownMs=shown});}pet.Hide();return new{cycles=samples,staleNullDiscoveryBypassed=true,actualCodexNotManipulated=true};}}}
