        pet.AdvanceOnce();pet.Motion.Position=new PointF(pet.AllowedBounds.Left+pet.AllowedBounds.Width/2-pet.Width/2,pet.AllowedBounds.Top+pet.AllowedBounds.Height/2-pet.Height/2);pet.Motion.ReactionRemaining=0;pet.AdvanceOnce();pet.OpenPanel(true);Pump(350);pet.ResumeAutonomy();pet.Motion.Velocity=new PointF(100,0);var atlas=Field<PetAtlas>(pet,"atlas");var director=Field<PetAnimationDirector>(pet,"director");Invoke(director,"Begin",9+index,"physics",Field<Stopwatch>(pet,"watch").Elapsed.TotalSeconds);typeof(PetAnimationDirector).GetField("lastPhysics",Hidden).SetValue(director,12);Invoke(pet,"Present");var action=pack.Actions[index];var origin=pet.Motion.Position;double firstTravel=-1,firstShown=-1,firstTravelClock=-1,travelled=0;int leading=0,trailing=0;var clock=Stopwatch.StartNew();PointF tail=PointF.Empty;
