    public static int RunSwitch(string root,string report,string state){try{var result=Switching(root,report,PetPack.Discover(root,state));File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=true,checks,result}));return 0;}catch(Exception e){File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=false,checks,error=e.ToString()}));return 1;}}
    static object Switching(string root,string report,List<PetPack> packs){string isolated=Path.Combine(Path.GetDirectoryName(report),"switching-state");new PetPreferences{ShowQuota=false,CodexOnly=false,Roaming=false,Sound=false,PositionVersion=1}.Save(isolated);using(var owner=new Form()){IntPtr handle=owner.Handle;using(var controller=new PetController(owner,root,isolated,true))using(var heartbeat=new System.Windows.Forms.Timer{Interval=10}){controller.Packs=packs;var clock=Stopwatch.StartNew();long previous=0,maxGap=0,startupGap=0;heartbeat.Tick+=delegate{long now=clock.ElapsedMilliseconds;if(previous>0)maxGap=Math.Max(maxGap,now-previous);previous=now;};heartbeat.Start();var samples=new List<object>();foreach(var pack in packs.Where(p=>p.Available)){var click=Stopwatch.StartNew();var old=controller.Window;controller.Select(pack);long clickMs=click.ElapsedMilliseconds;Need(old==null||controller.Window==old,"Old pet was disposed before replacement was ready");var wait=Stopwatch.StartNew();while(controller.IsPreparing&&wait.ElapsedMilliseconds<6000)Pump(10);Need(!controller.IsPreparing&&controller.SwitchError==null&&controller.Window!=null,"Async selection failed: "+pack.Id+" "+controller.SwitchError);Need(clickMs<150,"Selection blocked UI: "+pack.Id+" "+clickMs);samples.Add(new{id=pack.Id,selectCallMs=clickMs,readyMs=controller.LastSwitchMilliseconds,stages=controller.LastSwitchStages});if(old==null){startupGap=maxGap;maxGap=0;previous=0;}}heartbeat.Stop();Need(maxGap<250,"Switching stalls UI heartbeat: "+maxGap+" "+new JavaScriptSerializer().Serialize(samples));Need(!owner.Visible,"Switch test activated a manager");return new{pets=samples,maximumUiHeartbeatGapMs=maxGap,initialStartupUiGapMs=startupGap,oldPetKeptUntilReady=true};}}
    }
